#include "tt_metal/fabric/debug/visualizer/common/fabric_visualizer_build_identity.hpp"

// Generated by CMake. This is the only visualizer file that includes it, so a new commit recompiles only this file.
#include <tt_metal/impl/version.hpp>

namespace tt::tt_fabric::visualizer {

BuildIdentity get_build_identity() {
    return {
        .git_sha = tt::tt_metal::kGitSha,
        .git_sha_short = tt::tt_metal::kGitShaShort,
        .version = tt::tt_metal::kVersionFull,
        .build_type = tt::tt_metal::kBuildType,
        .git_dirty = tt::tt_metal::kGitDirty,
    };
}

}  // namespace tt::tt_fabric::visualizer
